def parse_tls_record(data):
    """
    Parse a TLS record layer message.
    Returns: (content_type, version, length, payload)
    """
    if len(data) < 5:
        return None
    content_type = data[0]
    version = struct.unpack('!H', data[1:3])[0]
    length = struct.unpack('!H', data[3:5])[0]
    payload = data[5:5+length]
    return content_type, version, length, payload

def parse_handshake_message(payload):
    """
    Parse a TLS handshake message.
    Returns: (msg_type, length, handshake_payload)
    """
    if len(payload) < 4:
        return None
    msg_type = payload[0]
    length = struct.unpack('!I', b'\x00' + payload[1:4])[0]  # 3-byte length
    handshake_payload = payload[4:4+length]
    return msg_type, length, handshake_payload

